return [{ json: {
    spreadsheet_id: 'REPLACE_WITH_SPREADSHEET_ID',
    telegram_chat_id: 'REPLACE_WITH_TELEGRAM_CHAT_ID',
    source_url: 'https://webscraper.io/test-sites/e-commerce/static/computers/laptops',
    page_limit: 200, page_delay_seconds: 1, request_timeout_ms: 10000,
  } }];

const config = $input.first().json;
  if (!/^[A-Za-z0-9_-]+$/.test(config.spreadsheet_id) || config.spreadsheet_id.startsWith('REPLACE_')
    || !/^(?:-?\d+|@[A-Za-z0-9_]+)$/.test(config.telegram_chat_id)) {
    throw new Error('Yapılandırma: Spreadsheet ID ve Telegram chat ID doldurulmalı. Sayfa: ' + config.source_url);
  }
  if (config.source_url !== 'https://webscraper.io/test-sites/e-commerce/static/computers/laptops'
    || !Number.isInteger(config.page_limit) || config.page_limit < 2 || config.page_limit > 1000
    || config.page_delay_seconds < 1 || config.page_delay_seconds > 30
    || config.request_timeout_ms < 1000 || config.request_timeout_ms > 30000) throw new Error('Geçersiz tarama ayarları.');
  const scraped_at = new Date().toISOString();
  return [{ json: { ...config, run_id: `run-${$execution.id}-${Date.now()}`, scraped_at,
    page: 1, last_page: 1, visited_pages: [], products: [] }, pairedItem: { item: 0 } }];

const state = $input.first().json;
  if (!Number.isInteger(state.page) || state.page < 1 || state.page >= state.page_limit
    || state.visited_pages.includes(state.page)) throw new Error('Sayfa döngüsü/sınırı geçersiz: ' + state.source_url);
  return [{ json: { ...state, page_url: `${state.source_url}?page=${state.page}` }, pairedItem: { item: 0 } }];

const state = $('Page State').itemMatching(0).json;
  const response = $input.first().json;
  if (!Number.isInteger(response.statusCode) || response.statusCode < 200 || response.statusCode >= 300
    || typeof response.body !== 'string' || !response.body.trim()) {
    throw new Error(`Sayfa alınamadı veya boş HTTP yanıtı (${response.statusCode ?? 'bilinmiyor'}): ${state.page_url}`);
  }
  return [{ json: { state, html: response.body }, pairedItem: { item: 0 } }];

const state = $('Check HTTP').itemMatching(0).json.state;
  const extracted = $input.first().json;
  const fail = reason => { throw new Error(`${reason} | Sayfa: ${state.page_url}`); };
  if (!Array.isArray(extracted.cards) || extracted.cards.length === 0) fail('Hiç ürün bulunamadı');
  if (!Array.isArray(extracted.page_links)) fail('Sayfalama çıkarımı geçersiz');
  const origin = 'https://webscraper.io';
  const categoryPath = state.source_url.slice(origin.length);
  let last_page = Math.max(state.last_page, state.page);
  for (const raw of extracted.page_links) {
    if (typeof raw !== 'string' || !raw.trim()) fail('Boş sayfalama hedefi');
    const href = raw.trim();
    const absolute = href.startsWith('?') ? state.source_url + href
      : href.startsWith('/') && !href.startsWith('//') ? origin + href : href;
    if (!absolute.startsWith(origin + categoryPath + '?page=')) fail('Kategori dışı sayfalama hedefi');
    const tail = absolute.slice((origin + categoryPath + '?page=').length);
    if (!/^[1-9]\d*$/.test(tail)) fail('Geçersiz sayfa numarası');
    const page = Number(tail);
    if (!Number.isSafeInteger(page) || page >= state.page_limit) fail('Sayfa güvenlik sınırına ulaşıldı; tarama tamamlanmadı');
    last_page = Math.max(last_page, page);
  }
  const active = extracted.active_page;
  if (Array.isArray(active) && active.length && (active.length !== 1 || Number(active[0]) !== state.page)) fail('İstenen ve dönen sayfa numarası farklı');
  return extracted.cards.map((card_html, index) => {
    if (typeof card_html !== 'string' || !card_html.trim()) fail('Boş ürün kartı');
    return { json: { card_html, card_index: index, state: { ...state, last_page, expected_cards: extracted.cards.length } }, pairedItem: { item: 0 } };
  });

const items = $input.all();
  const originals = items.map((_, index) => $('Expand Cards').itemMatching(index).json);
  const state = originals[0]?.state;
  if (!state || items.length === 0) throw new Error('Ürün kartları kayboldu; tarama tamamlanmadı.');
  const fail = reason => { throw new Error(`${reason} | Sayfa: ${state.page_url}`); };
  if (items.length !== state.expected_cards) fail('Eksik ürün kartı çıktısı; sayfa tamamlanmadı');
  const one = (values, label) => {
    if (!Array.isArray(values) || values.length !== 1 || typeof values[0] !== 'string' || !values[0].trim()) fail(`Eksik/çoklu ${label}`);
    return values[0].trim();
  };
  const seen = new Set(state.products.map(product => product.product_url));
  const current = items.map((item, index) => {
    if (originals[index].state.page !== state.page || originals[index].card_index !== index) fail('Ürün kartı eşleştirmesi bozuldu');
    const data = item.json;
    const names = data.names;
    if (!Array.isArray(names) || names.length !== 1) fail('Eksik/çoklu ürün başlığı');
    const product_name = typeof names[0] === 'string' && names[0].trim() ? names[0].trim() : one(data.labels, 'ürün adı');
    const priceText = one(data.prices, 'fiyat');
    if (!/^\$(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d{1,2})?$/.test(priceText)) fail('Geçersiz fiyat');
    const price = Number(priceText.slice(1).replace(/,/g, ''));
    if (!Number.isFinite(price) || price < 0 || !Number.isSafeInteger(Math.round(price * 100))) fail('Geçersiz fiyat');
    const reviews = one(data.reviews, 'yorum sayısı');
    if (!/^\d+$/.test(reviews)) fail('Geçersiz yorum sayısı');
    const review_count = Number(reviews);
    if (!Number.isSafeInteger(review_count)) fail('Geçersiz yorum sayısı');
    const href = one(data.urls, 'ürün URL');
    const product_url = href.startsWith('/') && !href.startsWith('//') ? 'https://webscraper.io' + href : href;
    if (!/^https:\/\/webscraper\.io\/test-sites\/e-commerce\/static\/product\/\d+$/.test(product_url)) fail('Geçersiz ürün URL');
    if (seen.has(product_url)) fail('Yinelenen ürün URL; eksik/tekrarlı sayfa olabilir');
    seen.add(product_url);
    return { product_name, price, review_count, product_url };
  });
  return [{ json: { ...state, products: [...state.products, ...current],
    visited_pages: [...state.visited_pages, state.page], page: state.page + 1,
    more_pages: state.page < state.last_page }, pairedItem: items.map((_, item) => ({ item })) }];

const state = $input.first().json;
  if (state.more_pages || state.last_page >= state.page_limit || state.products.length === 0
    || state.visited_pages.length !== state.last_page
    || state.visited_pages.some((page, index) => page !== index + 1)) {
    throw new Error('Eksik tarama; snapshot yazılmayacak. Sayfa: ' + state.page_url);
  }
  return [{ json: { ...state, product_count: state.products.length }, pairedItem: { item: 0 } }];

const scan = $('Finalize Scan').first().json;
  if ($input.all().some(item => item.error || Object.hasOwn(item.json, 'error'))) throw new Error('Google Sheets runs okuması başarısız; boş geçmiş kabul edilmedi. Kaynak: ' + scan.source_url);
  const rows = $input.all().map(item => item.json).filter(row => Object.keys(row).length > 0);
  const runs = rows.map(row => {
    const count = typeof row.product_count === 'string' && /^\d+$/.test(row.product_count) ? Number(row.product_count) : row.product_count;
    if (typeof row.run_id !== 'string' || !row.run_id.trim() || typeof row.completed_at !== 'string'
      || !Number.isFinite(Date.parse(row.completed_at)) || !Number.isSafeInteger(count) || count < 1) {
      throw new Error('runs tablosunda geçersiz tamamlanma kaydı. Kaynak: ' + scan.source_url);
    }
    return { run_id: row.run_id, completed_at: row.completed_at, product_count: count };
  });
  if (new Set(runs.map(run => run.run_id)).size !== runs.length) throw new Error('runs tablosunda yinelenen run_id.');
  runs.sort((a, b) => Date.parse(b.completed_at) - Date.parse(a.completed_at) || b.run_id.localeCompare(a.run_id));
  return [{ json: { ...scan, previous_run: runs[0] ?? null }, pairedItem: { item: 0 } }];

const state = $('Select Previous Run').first().json;
  if ($input.all().some(item => item.error || Object.hasOwn(item.json, 'error'))) throw new Error('Google Sheets snapshots okuması başarısız; boş geçmiş kabul edilmedi. Kaynak: ' + state.source_url);
  const rows = $input.all().map(item => item.json);
  const prior = state.previous_run;
  const previous = new Map();
  const cents = value => {
    if (typeof value !== 'number' && (typeof value !== 'string' || !/^\d+(?:\.\d{1,2})?$/.test(value.trim()))) throw new Error('Geçmiş snapshot fiyatı geçersiz.');
    const number = Number(value);
    const result = Math.round(number * 100);
    if (!Number.isFinite(number) || number < 0 || !Number.isSafeInteger(result)) throw new Error('Geçmiş snapshot fiyatı geçersiz.');
    return result;
  };
  if (prior) {
    const selected = rows.filter(row => row.run_id === prior.run_id);
    if (selected.length !== prior.product_count) throw new Error('Tamamlanmış çalışma ile snapshot sayısı uyuşmuyor; geçmiş güvenilir değil.');
    for (const row of selected) {
      if (typeof row.product_url !== 'string' || !/^https:\/\/webscraper\.io\/test-sites\/e-commerce\/static\/product\/\d+$/.test(row.product_url)
        || previous.has(row.product_url)) throw new Error('Geçmiş snapshot URL geçersiz/yinelenen.');
      previous.set(row.product_url, cents(row.price));
    }
  }
  const changes = [];
  for (const product of state.products) {
    const old = previous.get(product.product_url);
    const current = cents(product.price);
    if (old === undefined) changes.push({ ...product, kind: 'new' });
    else if (old !== current) changes.push({ ...product, kind: 'price', old_price: old / 100 });
  }
  return [{ json: { ...state, changes, first_run: prior === null }, pairedItem: { item: 0 } }];

const state = $input.first().json;
  return state.products.map(product => ({ json: { run_id: state.run_id, scraped_at: state.scraped_at,
    product_url: product.product_url, product_name: product.product_name, price: product.price,
    review_count: product.review_count }, pairedItem: { item: 0 } }));

const state = $('Compare Snapshots').first().json;
  const written = $input.all().map(item => item.json);
  if (written.length !== state.products.length || written.some(row => row.run_id !== state.run_id)
    || new Set(written.map(row => row.product_url)).size !== state.products.length) {
    throw new Error('Snapshot yazımı tamamlanmadı; runs kaydı oluşturulmayacak. Kaynak: ' + state.source_url);
  }
  return [{ json: state, pairedItem: $input.all().map((_, item) => ({ item })) }];

const state = $input.first().json;
  const escape = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const fresh = state.changes.filter(change => change.kind === 'new').length;
  const changed = state.changes.length - fresh;
  const sheet = `https://docs.google.com/spreadsheets/d/${state.spreadsheet_id}/edit`;
  const header = `Laptop fiyat takibi\n${escape(state.scraped_at)}\nYeni: ${fresh} · Fiyat değişikliği: ${changed}${state.first_run ? '\nİlk çalışma: tüm ürünler yeni kabul edildi.' : ''}\n`;
  let body = '';
  let shown = 0;
  for (const change of state.changes) {
    const name = escape([...change.product_name].slice(0, 180).join(''));
    const price = change.kind === 'new' ? `$${change.price.toFixed(2)}` : `$${change.old_price.toFixed(2)} → $${change.price.toFixed(2)}`;
    const line = `\n${change.kind === 'new' ? 'Yeni' : 'Fiyat'}: ${name}\n${price}\n${escape(change.product_url)}\n`;
    if ((header + body + line).length > 3200) break;
    body += line;
    shown++;
  }
  const omitted = state.changes.length - shown;
  const text = header + body + (omitted ? `\nÖzet: ${omitted} ek değişiklik bu mesaja sığmadı.\n` : '\n')
    + `Tüm snapshot satırları (run_id: ${escape(state.run_id)}):\n${escape(sheet)}`;
  if (text.length > 3900) throw new Error('Telegram metin sınırı aşıldı.');
  return [{ json: { ...state, notification_text: text, has_changes: state.changes.length > 0 }, pairedItem: { item: 0 } }];

const data = $input.first().json;
  let page = data.page_url;
  if (!page) { try { page = $('Page State').itemMatching(0).json.page_url; } catch { page = 'https://webscraper.io/test-sites/e-commerce/static/computers/laptops'; } }
  const raw = typeof data.error === 'string' ? data.error : data.error?.message ?? data.message ?? 'Akış adımı başarısız oldu';
  const reason = String(raw).slice(0, 700);
  const failure = `Fiyat takibi BAŞARISIZ\nNeden: ${reason}\nİlgili sayfa/kaynak: ${page}\nTamamlanma kaydının durumu kontrol edilmeli; çalışma başarılı kabul edilmemeli.`;
  const escape = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return [{ json: { failure, telegram_text: escape(failure) }, pairedItem: { item: 0 } }];
